import { useEffect, useRef, useState } from 'react';

interface AmbientVideoBackgroundProps {
  className?: string;
  overlayOpacity?: number;
}

/**
 * 100% Seamless Boomerang / Forward-Reverse Video Loop.
 * The video was mathematically generated by joining forward (0->10s)
 * and reverse (10s->0) frames into a continuous 20-second loop.
 * First frame === Last frame with sub-pixel continuity.
 * Decoded natively by GPU with zero keyframe latency or canvas overhead.
 */
export default function AmbientVideoBackground({
  className = '',
  overlayOpacity = 0.42,
}: AmbientVideoBackgroundProps) {
  const videoRef = useRef<HTMLVideoElement | null>(null);
  const [isPlaying, setIsPlaying] = useState(true);
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;
    video.muted = true;
    video.playsInline = true;
    video.loop = true;
    video
      .play()
      .then(() => setIsPlaying(true))
      .catch(() => setIsPlaying(false));
  }, []);

  const togglePlay = () => {
    const video = videoRef.current;
    if (!video) return;
    if (video.paused) {
      video.play().then(() => setIsPlaying(true)).catch(() => {});
    } else {
      video.pause();
      setIsPlaying(false);
    }
  };

  return (
    <div
      className={`absolute inset-0 overflow-hidden pointer-events-none select-none z-0 ${className}`}
      aria-hidden="true"
    >
      {/* Native GPU-accelerated seamless boomerang loop */}
      <video
        ref={videoRef}
        src="/videos/hero-ambient-loop.mp4"
        muted
        playsInline
        autoPlay
        loop
        preload="auto"
        onLoadedData={() => setLoaded(true)}
        className="absolute inset-0 w-full h-full object-cover object-center"
        style={{ willChange: 'transform' }}
      />

      {/* Warm initial backdrop while video stream initializes */}
      {!loaded && (
        <div className="absolute inset-0 z-[1] bg-gradient-to-br from-[#1f1b17] via-[#141210] to-[#0d0c0a]" />
      )}

      {/* Primary directional architectural overlay */}
      <div
        className="absolute inset-0 z-[2] transition-opacity duration-1000"
        style={{
          opacity: overlayOpacity,
          background:
            'linear-gradient(135deg, rgba(10,9,8,0.72) 0%, rgba(18,16,14,0.45) 45%, rgba(10,9,8,0.78) 100%)',
        }}
      />

      {/* Left editorial text shield — soft warm vignette ensuring 100% legibility */}
      <div className="absolute inset-0 z-[2] bg-gradient-to-r from-black/85 via-black/55 to-black/20 pointer-events-none" />
      {/* Top navbar protection tint */}
      <div className="absolute inset-x-0 top-0 h-40 z-[2] bg-gradient-to-b from-black/65 via-black/25 to-transparent pointer-events-none" />

      {/* Bottom transition blend into white/ivory page content */}
      <div className="absolute inset-x-0 bottom-0 h-32 z-[2] bg-gradient-to-t from-black/40 to-transparent pointer-events-none" />

      {/* Warm golden specular highlight (architectural daylight ambience) */}
      <div className="absolute inset-0 z-[3] bg-[radial-gradient(ellipse_at_35%_25%,_rgba(197,168,128,0.18),transparent_60%)] pointer-events-none" />

      {/* Tactile micro-grain filter */}
      <div
        className="absolute inset-0 z-[4] opacity-[0.022] pointer-events-none mix-blend-overlay"
        style={{
          backgroundImage: `url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.8' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E")`,
        }}
      />

      {/* Ambient Play/Pause control */}
      <div className="absolute bottom-8 right-8 z-20 pointer-events-auto hidden sm:flex items-center gap-2">
        <button
          onClick={togglePlay}
          className="group w-10 h-10 rounded-full bg-white/10 hover:bg-white/20 backdrop-blur-xl border border-white/20 flex items-center justify-center transition-all duration-300 cursor-pointer shadow-lg hover:scale-105"
          aria-label={isPlaying ? 'Pause ambient video' : 'Play ambient video'}
          title={isPlaying ? 'Pause ambient video' : 'Play ambient video'}
        >
          {isPlaying ? (
            <svg className="w-3.5 h-3.5 text-white/90 group-hover:text-white" fill="currentColor" viewBox="0 0 24 24">
              <rect x="6" y="4" width="4" height="16" rx="1" />
              <rect x="14" y="4" width="4" height="16" rx="1" />
            </svg>
          ) : (
            <svg className="w-3.5 h-3.5 text-white/90 group-hover:text-white ml-0.5" fill="currentColor" viewBox="0 0 24 24">
              <path d="M8 5v14l11-7z" />
            </svg>
          )}
        </button>
      </div>
    </div>
  );
}
